public interface EventRsvpRepository extends JpaRepository<EventRsvp,Long>{ Optional<EventRsvp> findByEventAndUser(Event event,User user); List<EventRsvp> findByEventOrderByUserFullNameAsc(Event event); List<EventRsvp> findByUser(User user); long countByUserAndStatus(User user,EventRsvpStatus status); long countByUserAndStatusAndEventEventDateBetween(User user,EventRsvpStatus status,java.time.LocalDate start,java.time.LocalDate end); @org.springframework.data.jpa.repository.Query("select r.user.id, count(r) from EventRsvp r where r.status=:status and r.event.eventDate between :start and :end group by r.user.id") List<Object[]> attendanceCountsByUser(EventRsvpStatus status,java.time.LocalDate start,java.time.LocalDate end); void deleteByEvent(Event event); }
